        return{yongShen:yongShenElem+'(世爻)',yuanShen:yuanShenElem||'?',jiShen:jiShenElem||'?',chouShen:chouShenElem||'?',riChen:'需日辰',yueJian:'需月建',huiTouSheng:'需动爻判断',huiTouKe:'需动爻判断',yinGuaShen:'需卦身判断',yangGuaShen:'需卦身判断',guaMing:'需具体断卦',guaYan:'需具体断卦'};
