    function getWuxingFamily(binary){
        var tr=binaryToTrigrams(binary);
        var lower=tr.lower,upper=tr.upper;
        var li=TRIGRAMS[lower],up=TRIGRAMS[upper];
        var tiYong=getTiYong(binary);
        var tiXing={"金":"从革-刚硬肃杀","木":"曲直-生长舒展","水":"润下-流动趋低","火":"炎上-光明热烈","土":"稼穑-承载化育"};
        var wuQi={"金":"燥","木":"风","水":"寒","火":"热","土":"湿"};
        var wuHua={"金":"收","木":"生","水":"藏","火":"长","土":"化"};
        var wuQing={"金":"悲","木":"怒","水":"恐","火":"喜","土":"思"};
        var wuSe={"金":"白","木":"青","水":"黑","火":"赤","土":"黄"};
        var wuWei={"金":"辛","木":"酸","水":"咸","火":"苦","土":"甘"};
        var wuYin={"金":"商","木":"角","水":"羽","火":"徵","土":"宫"};
        var wuChang={"金":"义","木":"仁","水":"智","火":"礼","土":"信"};
        var liElem=li["element"],upElem=up["element"];
        var xiangSheng='无相生';
        if(WUXING_SHENG[liElem]===upElem)xiangSheng=liElem+'生'+WUXING_SHENG[liElem];
        else if(WUXING_SHENG[upElem]===liElem)xiangSheng=upElem+'生'+WUXING_SHENG[upElem];
        var xiangKe='无相克';
        if(WUXING_KE[liElem]===upElem)xiangKe=liElem+'克'+WUXING_KE[liElem];
        else if(WUXING_KE[upElem]===liElem)xiangKe=upElem+'克'+WUXING_KE[upElem];
        var chengWu=WUXING_KE[liElem]===upElem?liElem+'乘'+upElem:'无乘';
        var muZi='非母子';
        if(WUXING_SHENG[liElem]===upElem)muZi=liElem+'母'+upElem+'子';
        else if(WUXING_SHENG[upElem]===liElem)muZi=upElem+'母'+liElem+'子';
        var zhiHua=WUXING_KE[liElem]===upElem?liElem+'制'+upElem:'无制化关系';
        return{
            tiXingLower:tiXing[liElem]||'?',tiXingUpper:tiXing[upElem]||'?',
            xiangSheng:xiangSheng,xiangKe:xiangKe,chengWu:chengWu,muZi:muZi,zhiHua:zhiHua,
            wangShuaiRelation:tiYong.relation,
            wuFang:li["direction"]+'+'+up["direction"],wuJi:li["season"]+'+'+up["season"],
            wuQi:(wuQi[liElem]||'?')+'+'+(wuQi[upElem]||'?'),
            wuHua:(wuHua[liElem]||'?')+'+'+(wuHua[upElem]||'?'),
            wuQing:(wuQing[liElem]||'?')+'+'+(wuQing[upElem]||'?'),
            wuSe:(wuSe[liElem]||'?')+'+'+(wuSe[upElem]||'?'),
            wuWei:(wuWei[liElem]||'?')+'+'+(wuWei[upElem]||'?'),
            wuYin:(wuYin[liElem]||'?')+'+'+(wuYin[upElem]||'?'),
            wuChang:(wuChang[liElem]||'?')+'+'+(wuChang[upElem]||'?'),
            yinYangHuCang:'下卦'+liElem+'('+li["family"]+')上卦'+upElem+'('+up["family"]+')',
            liuQinMapping:getWuxingRelation(upElem,liElem)
        };
    }

    function getBoshuOrder(name){
        var idx=BOSHU_ORDER_COMPLETE.indexOf(name);
        return idx>=0?idx+1:-1;
    }

    function calcShiLiuBian(name,binary){
        var palaces=[
            {n:"乾",b:"111111"},{n:"坤",b:"000000"},{n:"震",b:"100000"},
            {n:"巽",b:"010000"},{n:"坎",b:"101010"},{n:"离",b:"010101"},
            {n:"艮",b:"110000"},{n:"兑",b:"000101"}
        ];
        var posName=["本宫原卦","一世(初爻变)","二世(二爻变)","三世(三爻变)","四世(四爻变)","五世(五爻变)","上世(上爻变=游魂)","游魂","归魂"];
        for(var p=0;p<palaces.length;p++){
            var pBin=palaces[p].b;
            var diffs=[];
            for(var i=0;i<6;i++){if(binary[i]!==pBin[i])diffs.push(i);}
            var pos="";
            if(diffs.length===0)pos="本宫原卦";
            else if(diffs.length===1&&diffs[0]===0)pos="一世(初爻变)";
            else if(diffs.length===2&&diffs[0]===0&&diffs[1]===1)pos="二世(二爻变)";
            else if(diffs.length===3&&diffs[0]===0&&diffs[1]===1&&diffs[2]===2)pos="三世(三爻变)";
            else if(diffs.length===4&&diffs[0]===0&&diffs[1]===1&&diffs[2]===2&&diffs[3]===3)pos="四世(四爻变)";
            else if(diffs.length===5&&diffs[0]===0&&diffs[1]===1&&diffs[2]===2&&diffs[3]===3&&diffs[4]===4)pos="五世(五爻变)";
            else if(diffs.length===6)pos="上世(六爻变)";
            else if(diffs.length===4&&diffs.indexOf(3)>=0&&diffs.indexOf(4)<0)pos="游魂卦";
            else if(diffs.length<=2&&diffs.indexOf(0)<0&&diffs.indexOf(1)<0&&diffs.indexOf(2)<0)pos="归魂卦";
            if(pos)return palaces[p].n+"宫·"+pos;
        }
        return "八宫十六变序列";
    }

    function calcQiShiErHou(month,day){
        var terms=["小寒","大寒","立春","雨水","惊蛰","春分","清明","谷雨","立夏","小满","芒种","夏至","小暑","大暑","立秋","处暑","白露","秋分","寒露","霜降","立冬","小雪","大雪","冬至"];
        var msgGua=["复","临","泰","大壮","夬","乾","姤","遁","否","观","剥","坤"];
        var mi=month-1;
        if(mi<0)mi=0;if(mi>11)mi=11;
        var pentad=Math.floor((day-1)/10);
        if(pentad>2)pentad=2;
        var pentadNames=["初候","二候","三候"];
        return terms[mi*2]+"·"+pentadNames[pentad]+" 配十二消息卦:"+msgGua[mi];
    }

