        var hetuNum=(HETU[TRIGRAMS[lower]["element"]]||'?')+'/'+(HETU[TRIGRAMS[upper]["element"]]||'?');
        var luoshuNum=(LUOSHU[upper]||'?')+'/'+(LUOSHU[lower]||'?');
        var msg='非消息卦';
